reply:
```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment>
  a owl:Ontology ;
  rdfs:comment """Ontology of educational assessment built from a corpus that mixes several
  orthogonal classification axes (purpose, objectivity, referencing, formality, locus,
  standardization, stakes, granularity, validity, reliability, rubric type, grading type).
  Design note: the corpus explicitly states that a single test can carry multiple
  classifications at once ('Most tests can be classified on multiple categories... a test
  can be both standardized and also a high-stakes test'). Each axis is therefore reified as
  its own functional property with a disjoint value-partition, and named kinds are defined
  as equivalentClass bridges. This allows cross-axis membership (e.g. a CompetitiveExamination
  is simultaneously norm-referenced and high-stakes) while keeping WITHIN-axis siblings
  disjoint, matching the corpus's own logic.""" .

#################################################################
# CORE
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning." .

ea:Test a owl:Class ;
  rdfs:label "Test" ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Assessment is often used interchangeably with test but is not limited to tests; Test is therefore modeled as a subclass of Assessment." .

ea:Examination owl:equivalentClass ea:Test ;
  rdfs:label "Examination" ;
  skos:altLabel "exam" , "evaluation" .

#################################################################
# AXIS 1: GRANULARITY
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:GranularityLevel .

ea:GranularityLevel a owl:Class ;
  rdfs:comment "Assessment can focus on the individual learner, the learning community, a course, an academic program, the institution, or the educational system as a whole." ;
  owl:disjointUnionOf ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
                        ea:AcademicProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

ea:LearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:AcademicProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .

#################################################################
# AXIS 2: PURPOSE / TIMING  (Placement, Formative, Summative, Diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class ;
  rdfs:comment "One corpus passage divides assessment into four coordinate purposes (placement, formative, summative, diagnostic); another divides it into only three (initial, formative, summative), treating 'initial'/'placement'/'pre-assessment' as synonyms. Both schemes are encoded." ;
  owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PlacementAssessment a owl:Class ;
  rdfs:label "PlacementAssessment" ;
  skos:altLabel "initial assessment" , "pre-assessment" , "threshold knowledge test" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
  rdfs:label "FormativeAssessment" ;
  skos:altLabel "educative assessment" , "assessment for learning" , "classroom assessment" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
  rdfs:label "SummativeAssessment" ;
  skos:altLabel "assessment of learning" , "summative evaluation" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
  rdfs:label "DiagnosticAssessment" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists diagnostic assessment as a 4th purpose coordinate with (and disjoint from) formative assessment, while another states 'A common form of formative assessment is diagnostic assessment', i.e. subordinates it. Both the disjointness (via the PurposeCategory partition) and the subClassOf axiom are asserted, even though jointly they force DiagnosticAssessment toward emptiness under strict OWL semantics." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ea:DiagnosticAssessment ) .

ea:SelfAssessment a owl:Class ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Continuous assessment evaluates a student's progress throughout a course and will often include some form of formative assessment." ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasComponentAssessment ; owl:someValuesFrom ea:FormativeAssessment ] .

ea:hasComponentAssessment a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Assessment .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

ea:InterimAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Periodic/benchmark assessment used to predict performance on later summative assessments. TENSION: 'Some educators consider interim tests to be formative... but others may consider them to be summative' -- deliberately left unclassified under hasPurpose to reflect this unresolved debate." .

ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .

#################################################################
# Performance-based / Authentic assessment (contested relationship)
#################################################################

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:label "PerformanceBasedAssessment" ;
  skos:altLabel "performance assessment" ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Similar to summative assessment in that it focuses on achievement (not modeled as subClassOf SummativeAssessment because the corpus only states similarity, not subsumption)." .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment .

ea:PerformanceBasedAssessment owl:disjointWith ea:AuthenticAssessment .
ea:PerformanceBasedAssessment owl:equivalentClass ea:AuthenticAssessment .
ea:AuthenticAssessment rdfs:comment "TENSION: one coordinate list ('Performance-based assessments / Authentic assessment') presents these as distinct sibling kinds (encoded via disjointWith), while the Glossary states 'Performance assessments may also be called authentic assessments' (encoded via equivalentClass)." .

ea:hasPerformanceFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ; rdfs:range ea:PerformanceFormatCategory .

ea:PerformanceFormatCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ProductFormat ea:PerformanceEventFormat ) ;
  rdfs:comment "Performance formats are further classified into products and performances." .

ea:ProductFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceEventFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .

ea:ProductBasedPerformanceAssessment owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( ea:PerformanceBasedAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPerformanceFormat ; owl:someValuesFrom ea:ProductFormat ] ) ] .

ea:PerformanceEventAssessment owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( ea:PerformanceBasedAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPerformanceFormat ; owl:someValuesFrom ea:PerformanceEventFormat ] ) ] .

#################################################################
# AXIS 3: OBJECTIVITY (Objective / Subjective)
#################################################################

ea:hasAnswerStructure a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AnswerStructureCategory .

ea:AnswerStructureCategory a owl:Class ;
  owl:disjointUnionOf ( ea:SingleCorrectAnswerStructure ea:MultipleCorrectAnswerStructure ) .

ea:SingleCorrectAnswerStructure a owl:Class ; rdfs:subClassOf ea:AnswerStructureCategory .
ea:MultipleCorrectAnswerStructure a owl:Class ; rdfs:subClassOf ea:AnswerStructureCategory .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerStructure ; owl:someValuesFrom ea:SingleCorrectAnswerStructure ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerStructure ; owl:someValuesFrom ea:MultipleCorrectAnswerStructure ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer." .

[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveAssessment ea:SubjectiveAssessment ) .

#################################################################
# ASSESSMENT ITEMS
#################################################################

ea:AssessmentItem a owl:Class ; rdfs:label "AssessmentItem" ;
  rdfs:comment "An item consists of a stem and alternative answers; 'question' is a misnomer since not all items are phrased as questions." .

ea:isItemOf a owl:ObjectProperty ; rdfs:domain ea:AssessmentItem ; rdfs:range ea:Test .
ea:hasItem a owl:ObjectProperty ; owl:inverseOf ea:isItemOf ; rdfs:domain ea:Test ; rdfs:range ea:AssessmentItem .

ea:ObjectiveItem a owl:Class ; rdfs:subClassOf ea:AssessmentItem .
ea:SubjectiveItem a owl:Class ; rdfs:subClassOf ea:AssessmentItem .
ea:ObjectiveItem owl:disjointWith ea:SubjectiveItem .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ; skos:altLabel "MCQ" , "objective response" .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:comment "Contrasts with multiple-choice items: more than one answer may be keyed as correct." .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:FreeResponseQuestion owl:equivalentClass ea:EssayItem ; skos:altLabel "FRQ" , "essay question" .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:CalculationItem a owl:Class ; rdfs:subClassOf ea:AssessmentItem ;
  rdfs:comment "Mathematics/calculation items do not fall cleanly into objective or subjective categories; marks are often given for steps, not only the final answer." .
ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:AssessmentItem .

ea:TrueFalseFamilyItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem .
ea:OneBestAnswerItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem .
[] a owl:AllDisjointClasses ; owl:members ( ea:TrueFalseFamilyItem ea:OneBestAnswerItem ) .

ea:hasStem a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range xsd:string .
ea:ResponseOption a owl:Class .
ea:Key a owl:Class ; rdfs:subClassOf ea:ResponseOption .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:ResponseOption .
ea:Key owl:disjointWith ea:Distractor .
ea:hasOption a owl:ObjectProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:ResponseOption .
ea:hasKey a owl:ObjectProperty, owl:FunctionalProperty ; rdfs:subPropertyOf ea:hasOption ; rdfs:range ea:Key ;
  rdfs:comment "Only one answer may be keyed as correct." .
ea:hasDistractor a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ; rdfs:range ea:Distractor .

#################################################################
# AXIS 4: REFERENCING (Criterion / Norm / Ipsative)
#################################################################

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory .

ea:ReferencingCategory a owl:Class ;
  owl:disjointUnionOf ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) ;
  rdfs:comment "Test results can be compared against a criterion, against other students, or against previous performance." .

ea:CriterionReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .

ea:CriterionReferencedAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "normative assessment" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] ;
  rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:CriterionReferencedAssessment ea:NormReferencedAssessment ea:IpsativeAssessment ) .

ea:CriterionReferencedTest a owl:Class ; rdfs:subClassOf ea:Test ;
  skos:altLabel "CRT" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

ea:NormReferencedTest a owl:Class ; rdfs:subClassOf ea:Test ;
  skos:altLabel "NRT" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:MasteryTest a owl:Class ; rdfs:subClassOf ea:CriterionReferencedTest ;
  rdfs:comment "A criterion-referenced test that involves a cutscore." .
ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:decimal .

ea:StandardsBasedAssessment owl:equivalentClass ea:CriterionReferencedAssessment ;
  skos:altLabel "standards-based assessment" , "standards-referenced assessment" ;
  rdfs:comment "Criterion-referenced tests have also been called standards-based assessments." .

ea:NormGroup a owl:Class ; skos:altLabel "norming group" .
ea:hasNormGroup a owl:ObjectProperty ; rdfs:domain ea:NormReferencedTest ; rdfs:range ea:NormGroup .

#################################################################
# AXIS 5: FORMALITY (Formal / Informal)
#################################################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class ; owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .
ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .

ea:FormalAssessment owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] .
ea:InformalAssessment owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:FormalAssessment ea:InformalAssessment ) .

#################################################################
# AXIS 6: LOCUS (Internal / External)
#################################################################

ea:hasLocus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:LocusCategory .

ea:LocusCategory a owl:Class ; owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .
ea:InternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:ExternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .

ea:InternalAssessment owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] ;
  rdfs:comment "Set and marked by the school." .
ea:ExternalAssessment owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

[] a owl:AllDisjointClasses ; owl:members ( ea:InternalAssessment ea:ExternalAssessment ) .

#################################################################
# AXIS 7: STANDARDIZATION
#################################################################

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .
ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ; rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
  rdfs:comment "Administered and scored in a consistent or standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ; rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] ;
  rdfs:comment "Flexible in scope and format, variable in difficulty." .

[] a owl:AllDisjointClasses ; owl:members ( ea:StandardizedTest ea:NonStandardizedTest ) .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Backward-looking: measures knowledge/skills already learned." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Forward-looking: attempts to predict ability to succeed in a future endeavor." .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

#################################################################
# AXIS 8: STAKES
#################################################################

ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class ; owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .
ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .

ea:HighStakesTest a owl:Class ; rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "A test with a desired reward or important consequence for good/poor performance." .

ea:LowStakesTest a owl:Class ; rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:HighStakesTest ea:LowStakesTest ) .

ea:CompetitiveExamination a owl:Class ; rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
      ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ]
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected." .

#################################################################
# AXIS 9: ADMINISTRATION MODE
#################################################################

ea:hasAdministrationMode a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AdministrationModeCategory .

ea:AdministrationModeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:VerbalMode ea:WrittenMode ea:ComputerMode ea:PracticalMode ) .
ea:VerbalMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:WrittenMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:ComputerMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:PracticalMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .

ea:WrittenTest a owl:Class ; rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:WrittenMode ] ) ] .

ea:PerformanceTest a owl:Class ; rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:PracticalMode ] ) ] ;
  rdfs:comment "Requires an examinee to actually perform a task or activity rather than answer questions about it." .

#################################################################
# Specific named tests (not forced disjoint; coordinate mentions only)
#################################################################

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "A brief assessment, usually a formative, low-stakes assessment." .
ea:MidtermExam a owl:Class ; rdfs:subClassOf ea:Examination .
ea:FinalExam a owl:Class ; rdfs:subClassOf ea:Examination .
ea:ComplexAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Requires a rubric and an expert examiner, e.g. a thesis or funding proposal; complexity is due to format implicitness." .

#################################################################
# GLOSSARY-STYLE COORDINATE LISTS (explicitly stated to overlap -> NOT forced disjoint)
#################################################################

ea:PreAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "TENSION: elsewhere 'pre-assessment' is a synonym of PlacementAssessment, yet this Glossary passage enumerates PreAssessment and PlacementAssessment as separate coordinate purposes." .

ea:StandardsReferencedAssessment owl:equivalentClass ea:StandardsBasedAssessment .
ea:CommonAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used across a school/district to ensure consistent evaluation; may itself be formative or summative." .
ea:PortfolioBasedAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .
# No disjointness asserted among StandardsReferencedAssessment/CommonAssessment/PortfolioBasedAssessment/
# StandardizedTest/PerformanceBasedAssessment: the corpus explicitly states these design categories
# may co-occur ("a single test can have multiple qualities").

#################################################################
# Student portfolios
#################################################################

ea:StudentPortfolio a owl:Class ; rdfs:subClassOf ea:PortfolioBasedAssessment .
ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:StudentPortfolio ; skos:altLabel "e-portfolio" .
ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:StudentPortfolio .

#################################################################
# VALIDITY
#################################################################

ea:Validity a owl:Class ; rdfs:label "Validity" ;
  rdfs:comment "The degree to which a tool measures what it claims to measure." .
ea:hasValidity a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Validity .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:FaceValidity ea:ConsequentialValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: one passage lists content/criterion/construct/face/consequential validity as coordinate siblings (encoded as AllDisjointClasses), while another states 'Construct validity... subsumes all other types of validity', modeled here as ContentValidity and CriterionValidity being rdfs:subClassOf ConstructValidity." .

ea:hasCriterionTiming a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionValidity ; rdfs:range ea:CriterionTimingCategory .
ea:CriterionTimingCategory a owl:Class ; owl:disjointUnionOf ( ea:ConcurrentTiming ea:PredictiveTiming ) .
ea:ConcurrentTiming a owl:Class ; rdfs:subClassOf ea:CriterionTimingCategory .
ea:PredictiveTiming a owl:Class ; rdfs:subClassOf ea:CriterionTimingCategory .

ea:ConcurrentValidity owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:CriterionValidity
    [ a owl:Restriction ; owl:onProperty ea:hasCriterionTiming ; owl:someValuesFrom ea:ConcurrentTiming ] ) ] .
ea:PredictiveValidity owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:CriterionValidity
    [ a owl:Restriction ; owl:onProperty ea:hasCriterionTiming ; owl:someValuesFrom ea:PredictiveTiming ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:ConcurrentValidity ea:PredictiveValidity ) .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:ConvergentValidity owl:disjointWith ea:DiscriminantValidity .

#################################################################
