ea:hasErrorVariance a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .
ea:hasObservedScoreVariance a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .

# Taxonomy A: source of error ("four types of reliability")
ea:StudentRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:RaterRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
[] a owl:AllDisjointClasses ;
  owl:members ( ea:StudentRelatedReliability ea:RaterRelatedReliability
                ea:TestAdministrationRelatedReliability ea:TestRelatedReliability ) .

# Taxonomy B: estimation method ("several general classes of reliability estimates")
ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "inter-rater agreement" , "inter-observer reliability" .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ; skos:altLabel "repeatability" .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "parallel-forms reliability" , "alternate-forms reliability" .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
[] a owl:AllDisjointClasses ;
  owl:members ( ea:InterRaterReliability ea:TestRetestReliability
                ea:InterMethodReliability ea:InternalConsistencyReliability ) .

ea:Reliability rdfs:comment "TENSION: the corpus offers two different 'types of reliability' taxonomies -- one by error source (student/rater/test-administration/test-related) and one by estimation method (inter-rater/test-retest/inter-method/internal-consistency). Both are encoded as disjoint sibling sets under Reliability." .

ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:InternalConsistencyReliability ;
